// Static deployments ship the sidecar generated by build-wow. Pages can also serve the R2 release.
export async function onRequestGet({ env, next }) {
  if (!env.WOW_PACKAGES) return next();
  const key = 'survivalcraft-api.wow';
  const metadata = await env.WOW_PACKAGES.head(key);
  if (!metadata) return next();
  let hash = metadata.checksums?.sha256;
  if (!hash) {
    const object = await env.WOW_PACKAGES.get(key, { onlyIf: { etagMatches: metadata.etag } });
    if (!object?.body) return new Response('Release changed', { status: 409 });
    if (typeof crypto.DigestStream === 'function') {
      const digest = new crypto.DigestStream('SHA-256');
      await object.body.pipeTo(digest);
      hash = await digest.digest;
    } else {
      hash = await crypto.subtle.digest('SHA-256', await object.arrayBuffer());
    }
  }
  const hex = Array.from(new Uint8Array(hash), (byte) => byte.toString(16).padStart(2, '0')).join('');
  return new Response(hex + '\n', {
    headers: { 'Content-Type': 'text/plain', 'Cache-Control': 'no-cache', ETag: metadata.httpEtag },
  });
}
